"""
Self-Optimisation Engine
=========================

Monitors node and organoid network performance and triggers autonomous
remediation actions:

- Organoid cluster growth when utilisation is high
- Load redistribution across nodes
- Failure isolation and recovery
- Resource right-sizing
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Any

from thalos_prime.sbi.organoid import OrganoidNetwork, OrganoidState


@dataclass
class OptimisationAction:
    """A remediation action generated by the optimiser."""

    action_id: str = ""
    action_type: str = ""  # "grow_cluster", "rebalance", "isolate", "scale_down"
    description: str = ""
    target: str = ""
    executed: bool = False
    created_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))
    metadata: dict[str, Any] = field(default_factory=dict)


class SelfOptimiser:
    """
    Monitors the OrganoidNetwork and issues remediation actions
    automatically when predefined thresholds are breached.
    """

    HIGH_UTILISATION = 0.75
    LOW_HEALTH_THRESHOLD = 0.3
    SCALE_DOWN_UTILISATION = 0.10

    def __init__(self, network: OrganoidNetwork) -> None:
        self._network = network
        self._actions: list[OptimisationAction] = []

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def run_cycle(self) -> list[OptimisationAction]:
        """
        Execute one optimisation cycle.

        Analyses the network state and returns a list of actions taken.
        """
        import uuid

        report = self._network.health_report()
        new_actions: list[OptimisationAction] = []

        # --- High utilisation: grow the network ---
        if report.get("mean_utilisation", 0) > self.HIGH_UTILISATION:
            action = OptimisationAction(
                action_id=str(uuid.uuid4()),
                action_type="grow_cluster",
                description=(
                    f"Mean utilisation {report['mean_utilisation']:.1%} exceeds "
                    f"threshold {self.HIGH_UTILISATION:.0%}. Triggering organoid growth."
                ),
                target="organoid_network",
            )
            self._network.trigger_growth()
            action.executed = True
            new_actions.append(action)

        # --- Degraded clusters: isolate ---
        for cluster in self._network.clusters_by_state(OrganoidState.DEGRADED):
            action = OptimisationAction(
                action_id=str(uuid.uuid4()),
                action_type="isolate",
                description=(
                    f"Cluster {cluster.cluster_id[:8]} is degraded "
                    f"(health={cluster.health:.2f}). Deactivating."
                ),
                target=cluster.cluster_id,
            )
            cluster.deactivate()
            action.executed = True
            new_actions.append(action)

        # --- Idle clusters: scale down ---
        if (
            report.get("mean_utilisation", 1.0) < self.SCALE_DOWN_UTILISATION
            and report.get("total", 0) > 2
        ):
            # Deactivate one idle cluster
            idle = next(
                (
                    c
                    for c in self._network.clusters
                    if c.load == 0 and c.state == OrganoidState.ACTIVE
                ),
                None,
            )
            if idle:
                action = OptimisationAction(
                    action_id=str(uuid.uuid4()),
                    action_type="scale_down",
                    description=(
                        f"Scaling down idle cluster {idle.cluster_id[:8]}. "
                        f"Mean utilisation {report['mean_utilisation']:.1%}."
                    ),
                    target=idle.cluster_id,
                )
                idle.deactivate()
                action.executed = True
                new_actions.append(action)

        self._actions.extend(new_actions)
        return new_actions

    @property
    def action_history(self) -> list[OptimisationAction]:
        return list(self._actions)

    def report(self) -> dict[str, Any]:
        """Return a combined optimiser + network health report."""
        return {
            "network": self._network.health_report(),
            "actions_taken": len(self._actions),
            "last_actions": [
                {
                    "type": a.action_type,
                    "description": a.description,
                    "executed": a.executed,
                }
                for a in self._actions[-5:]
            ],
        }
